/** Neutral Lucide glyph keys rendered by TechIcon for technologies without an official brand glyph. */
export const glyphKeys = new Set(["REST APIs", "pgvector", "RAG", "testing"]);

// Only true aliases of an existing key (lower-case, version/parentheses already stripped); never a look-alike logo.
const aliases: Record<string, string> = {
  "postgres": "PostgreSQL", "tailwind": "Tailwind CSS", "gemini": "Gemini API", "gemini flash": "Gemini API",
  "langchain lcel": "LangChain", "rest api": "REST APIs", "rest apis": "REST APIs", "css": "CSS3", "css3": "CSS3",
  "drizzle": "Drizzle ORM", "ga4": "Google Analytics", "nvidia nim": "NVIDIA", "nvidia": "NVIDIA",
  "next": "Next.js", "node": "Node.js", "testing": "testing", "pgvector": "pgvector", "rag": "RAG",
};

/** Maps a displayed technology name ("Next.js 16", "FastAPI (async)", "Postgres") to an icon key, or null when it has none. */
export function resolveTechIconKey(name: string): string | null {
  const base = name.replace(/\s*\([^)]*\)/g, "").replace(/\s+v?\d+(\.\d+)*(?=\s|$)/gi, "").trim();
  if (!base) return null;
  if (brandIcons[base]) return base;
  const key = aliases[base.toLowerCase()] ?? Object.keys(brandIcons).find((k) => k.toLowerCase() === base.toLowerCase());
  return key && (brandIcons[key] || glyphKeys.has(key)) ? key : null;
}
